SELECT lead_id,vendor_lead_code,phone_code,phone_number,first_name,last_name,status,list_id,email,comments,state,entry_date,gmt_offset_now FROM vicidial_list WHERE list_id=910014 ORDER BY lead_id;
SELECT campaign_id,active,dial_method,auto_dial_level,dial_statuses,manual_dial_list_id,manual_preview_dial,manual_dial_filter,no_hopper_leads_logins,local_call_time FROM vicidial_campaigns WHERE campaign_id='QAOUT01';
SELECT user,campaign_id,status,conf_exten,extension,last_update_time FROM vicidial_live_agents;
SELECT event,user,campaign_id,event_date,UNIX_TIMESTAMP(event_date),user_group FROM vicidial_user_log WHERE user='qaagent14' ORDER BY event_date DESC LIMIT 20;
SELECT agent_log_id,user,campaign_id,event_time,UNIX_TIMESTAMP(event_time),pause_epoch,pause_sec,wait_epoch,wait_sec,talk_epoch,talk_sec,dispo_epoch,dispo_sec,sub_status FROM vicidial_agent_log WHERE user='qaagent14' ORDER BY agent_log_id DESC LIMIT 15;
SELECT lead_id,campaign_id,status FROM vicidial_hopper WHERE campaign_id='QAOUT01';
